package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;

@Service public class RecargoVentaService {
 private static final int SCALE=4;private final ConfiguracionRecargoVentaRepository configuraciones;private final ConfiguracionRecargoService configuracionService;private final LimiteRecargoRolRepository limites;private final TipoRecargoRepository tipos;private final MotivoRecargoVentaRepository motivos;private final ProductRepository productos;private final UsuarioEmpresaRepository accesos;private final MonedaRepository monedas;private final AutorizacionRecargoVentaRepository autorizaciones;private final PasswordEncoder passwordEncoder;private final AuditoriaService auditoria;
 public RecargoVentaService(ConfiguracionRecargoVentaRepository c,ConfiguracionRecargoService cs,LimiteRecargoRolRepository l,TipoRecargoRepository t,MotivoRecargoVentaRepository m,ProductRepository p,UsuarioEmpresaRepository a,MonedaRepository mo,AutorizacionRecargoVentaRepository au,PasswordEncoder pe,AuditoriaService ad){configuraciones=c;configuracionService=cs;limites=l;tipos=t;motivos=m;productos=p;accesos=a;monedas=mo;autorizaciones=au;passwordEncoder=pe;auditoria=ad;}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.recargos.aplicar')") public OpcionesRecargoPosDto opciones(){var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();var c=configuracionService.asegurar(p.tenantId(),e,p.usuarioId());if(!c.isEnabled())throw new ReglaNegocioException("Los recargos están deshabilitados para esta empresa.");String moneda=monedas.findByEmpresaIdAndMonedaBaseTrue(e).map(Moneda::getCodigoIso).orElse("—");var ts=tipos.findAllByTenantIdAndEmpresaIdAndActiveTrueOrderByNombre(p.tenantId(),e).stream().map(x->new ConfiguracionRecargoDto.Tipo(x.getId(),x.getNombre(),x.getTipoPredeterminado(),x.getValorPredeterminado(),x.getTratamientoFiscal(),x.isValorEditable(),true,x.getVersion())).toList();var ms=motivos.findAllByTenantIdAndEmpresaIdAndActiveTrueOrderByNombre(p.tenantId(),e).stream().map(x->new ConfiguracionRecargoDto.Motivo(x.getId(),x.getNombre(),x.isOtro(),true,x.getVersion())).toList();return new OpcionesRecargoPosDto(c.isPermiteVenta(),c.isPermiteLinea(),c.isPermitePorcentaje(),c.isPermiteMonto(),c.isRequiereMotivo(),c.isPermiteAutorizacion(),moneda,ts,ms);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.recargos.aplicar')") public VistaPreviaRecargoDto previsualizar(SolicitudVistaPreviaRecargoInput input){return calcular(input,true).vista();}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.recargos.solicitar_autorizacion')") public AutorizacionRecargoDto autorizar(AutorizarRecargoInput input){if(input==null||input.solicitud()==null)throw new ReglaNegocioException("La solicitud de autorización es obligatoria.");String usuario=input.usuario()==null?"":input.usuario().trim();if(usuario.isEmpty()||input.clave()==null||input.clave().isEmpty())throw new ReglaNegocioException("Indica el usuario y la contraseña del autorizador.");CalculoValidado c=calcular(input.solicitud(),true);if(!c.vista().requiereAutorizacion())throw new ReglaNegocioException("Este recargo no requiere autorización superior.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();UsuarioEmpresa solicitante=accesoActual(p,e);UsuarioEmpresa autorizador=accesos.findForAuthentication(e,usuario).filter(x->p.tenantId().equals(x.getUsuario().getTenantId())).orElseThrow(()->new ReglaNegocioException("Las credenciales del autorizador no son válidas."));if(!passwordEncoder.matches(input.clave(),autorizador.getUsuario().getPasswordHash()))throw new ReglaNegocioException("Las credenciales del autorizador no son válidas.");if(autorizador.getRol().getPermisos().stream().noneMatch(x->"facturas.recargos.autorizar".equals(x.getCodigo())))throw new ReglaNegocioException("El usuario no tiene permiso para autorizar recargos.");Limite limite=limites.findByTenantIdAndEmpresaIdAndRolIdAndActiveTrue(p.tenantId(),e,autorizador.getRol().getId()).map(x->new Limite(true,x.getPorcentajeMaximo(),x.getMontoMaximo())).orElse(new Limite(false,BigDecimal.ZERO,BigDecimal.ZERO));if(excede(c.vista().porcentajeEfectivo(),c.vista().montoRecargo(),limite))throw new ReglaNegocioException("El límite del autorizador no permite aprobar este recargo.");RecargoVentaInput d=input.solicitud().recargo();AutorizacionRecargoVenta a=new AutorizacionRecargoVenta(p.tenantId(),e,input.solicitud().operacionId(),p.usuarioId(),autorizador.getUsuario().getId(),solicitante.getRol().getId(),autorizador.getRol().getId(),d.alcance(),d.tipo(),d.conceptoId(),d.valor(),c.vista().baseElegible(),c.vista().montoRecargo(),fingerprint(input.solicitud(),c.vista()));a=autorizaciones.saveAndFlush(a);auditoria.registrar("SALES_SURCHARGE_AUTHORIZED","AutorizacionRecargoVenta",a.getId(),"{\"monto\":"+c.vista().montoRecargo()+"}");return new AutorizacionRecargoDto(a.getId(),autorizador.getUsuario().getUsuario());}
 @Transactional public ValidacionConfirmacion validarConfirmacion(UUID operacion,RecargoVentaInput recargo,List<LineaVistaPreviaRecargoInput> lineas){if(recargo==null)return sinRecargo(lineas);var p=TenantContext.principalActual();if(!p.permisos().contains("facturas.recargos.aplicar"))throw new ReglaNegocioException("No tienes permiso para aplicar recargos.");SolicitudVistaPreviaRecargoInput solicitud=new SolicitudVistaPreviaRecargoInput(operacion,recargo,lineas);CalculoValidado c=calcular(solicitud,false);AutorizacionRecargoVenta autorizacion=null;if(c.vista().requiereAutorizacion()){if(recargo.autorizacionId()==null)throw new ReglaNegocioException("El recargo requiere autorización superior.");autorizacion=autorizaciones.bloquear(recargo.autorizacionId(),p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("La autorización del recargo no es válida."));if(autorizacion.getEstado()!=EstadoAutorizacionRecargo.AUTHORIZED||!operacion.equals(autorizacion.getOperacionId())||!p.usuarioId().equals(autorizacion.getSolicitadaPor())||!fingerprint(solicitud,c.vista()).equals(autorizacion.getFingerprint()))throw new ReglaNegocioException("La autorización no corresponde al recargo actual. Solicita una nueva autorización.");}return new ValidacionConfirmacion(c.vista(),c.concepto(),c.motivo(),recargo,autorizacion==null?null:autorizacion.getId());}
 @Transactional public void consumirAutorizacion(UUID id,UUID factura){if(id==null)return;var p=TenantContext.principalActual();var a=autorizaciones.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("La autorización del recargo no es válida."));a.consumir(factura);autorizaciones.save(a);}
 private CalculoValidado calcular(SolicitudVistaPreviaRecargoInput input,boolean validarSolicitud){
  if(input==null||input.operacionId()==null||input.recargo()==null)throw new ReglaNegocioException("Los datos del recargo son obligatorios.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();var config=configuraciones.findByTenantIdAndEmpresaId(p.tenantId(),e).orElseGet(()->configuracionService.asegurar(p.tenantId(),e,p.usuarioId()));RecargoVentaInput d=input.recargo();
  if(!config.isEnabled())throw new ReglaNegocioException("Los recargos están deshabilitados para esta empresa.");if(d.alcance()==AlcanceRecargoVenta.SALE&&!config.isPermiteVenta())throw new ReglaNegocioException("El recargo general no está habilitado.");if(d.alcance()==AlcanceRecargoVenta.LINE&&!config.isPermiteLinea())throw new ReglaNegocioException("El recargo por producto no está habilitado.");if(d.tipo()==TipoRecargoVenta.PERCENTAGE&&!config.isPermitePorcentaje())throw new ReglaNegocioException("El recargo porcentual no está habilitado.");if(d.tipo()==TipoRecargoVenta.AMOUNT&&!config.isPermiteMonto())throw new ReglaNegocioException("El recargo por monto no está habilitado.");
  TipoRecargo concepto=tipos.findByIdAndTenantIdAndEmpresaId(d.conceptoId(),p.tenantId(),e).filter(TipoRecargo::isActivo).orElseThrow(()->new ReglaNegocioException("Selecciona un concepto de recargo activo."));if(!concepto.isValorEditable()&&(concepto.getTipoPredeterminado()!=d.tipo()||concepto.getValorPredeterminado()==null||concepto.getValorPredeterminado().compareTo(d.valor())!=0))throw new ReglaNegocioException("El valor del concepto de recargo no puede modificarse.");
  MotivoRecargoVenta motivo=null;if(d.motivoId()!=null)motivo=motivos.findByIdAndTenantIdAndEmpresaId(d.motivoId(),p.tenantId(),e).filter(MotivoRecargoVenta::isActivo).orElseThrow(()->new ReglaNegocioException("El motivo seleccionado no está disponible."));if(config.isRequiereMotivo()&&motivo==null)throw new ReglaNegocioException("Selecciona el motivo del recargo.");if(motivo!=null&&motivo.isOtro()&&(d.detalle()==null||d.detalle().isBlank()))throw new ReglaNegocioException("Indica el detalle del motivo Otro.");if(input.lineas()==null||input.lineas().isEmpty())throw new ReglaNegocioException("No hay productos en la venta para aplicar un recargo.");
  List<RecargoVentaCalculo.Linea> calculables=new ArrayList<>();Set<UUID> ids=new HashSet<>();for(var l:input.lineas()){if(l==null||l.lineaId()==null||l.productoId()==null||!ids.add(l.lineaId())||l.cantidad()==null||l.cantidad().signum()<=0)throw new ReglaNegocioException("Las líneas de la venta no son válidas.");Producto producto=productos.findByIdAndTenantIdAndEmpresaId(l.productoId(),p.tenantId(),e).filter(Producto::isActivo).orElseThrow(()->new RecursoNoEncontradoException("Producto no encontrado."));BigDecimal precio=scale(producto.getPrecioVenta());if(precio.compareTo(scale(l.precioEsperado()))!=0)throw new ReglaNegocioException("El precio de "+producto.getNombre()+" cambió. Actualiza la venta.");BigDecimal base=precio.multiply(l.cantidad()).subtract(scale(l.descuentoAplicado())).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal tasaBase=producto.getImpuestoVenta()!=null&&producto.getImpuestoVenta().isActivo()?producto.getImpuestoVenta().getPorcentaje():BigDecimal.ZERO;BigDecimal tasaRecargo=concepto.getTratamientoFiscal()==TratamientoFiscalRecargo.EXEMPT?BigDecimal.ZERO:tasaBase;calculables.add(new RecargoVentaCalculo.Linea(l.lineaId(),producto.getId(),base,tasaBase,tasaRecargo,producto.isPermiteRecargos()));}
  var r=RecargoVentaCalculo.calcular(d.alcance(),d.tipo(),d.valor(),d.lineaIds(),calculables);UsuarioEmpresa acceso=accesoActual(p,e);Limite limite=limites.findByTenantIdAndEmpresaIdAndRolIdAndActiveTrue(p.tenantId(),e,acceso.getRol().getId()).map(x->new Limite(true,x.getPorcentajeMaximo(),x.getMontoMaximo())).orElse(new Limite(false,BigDecimal.ZERO,BigDecimal.ZERO));boolean requiere=excede(r.porcentajeEfectivo(),r.montoRecargo(),limite);if(requiere&&!config.isPermiteAutorizacion())throw new ReglaNegocioException("El recargo supera el límite permitido para su usuario.");if(requiere&&validarSolicitud&&!p.permisos().contains("facturas.recargos.solicitar_autorizacion"))throw new ReglaNegocioException("El recargo supera tu límite y no tienes permiso para solicitar autorización.");var asignaciones=r.asignaciones().stream().map(x->new VistaPreviaRecargoDto.Asignacion(x.lineaId(),x.productoId(),x.baseComercial(),x.recargo(),x.baseImponible(),x.impuesto(),x.total())).toList();return new CalculoValidado(new VistaPreviaRecargoDto(r.baseElegible(),r.montoRecargo(),r.importePosterior(),r.porcentajeEfectivo(),requiere,limite.porcentaje(),limite.monto(),concepto.getNombre(),motivo==null?null:motivo.getNombre(),motivo!=null&&motivo.isOtro(),asignaciones),concepto,motivo);
 }
 private UsuarioEmpresa accesoActual(TenantPrincipal p,UUID e){return p.usuarioEmpresaId()!=null?accesos.findByIdAndEmpresaId(p.usuarioEmpresaId(),e).orElseThrow(()->new ReglaNegocioException("No fue posible determinar el rol del usuario.")):accesos.findByUsuarioIdAndEmpresaId(p.usuarioId(),e).orElseThrow(()->new ReglaNegocioException("No fue posible determinar el rol del usuario."));}
 private static boolean excede(BigDecimal p,BigDecimal m,Limite l){if(!l.configurado())return p.signum()>0||m.signum()>0;return l.porcentaje()!=null&&p.compareTo(l.porcentaje())>0||l.monto()!=null&&m.compareTo(l.monto())>0;}private static BigDecimal scale(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(SCALE,RoundingMode.HALF_UP);}
 private static ValidacionConfirmacion sinRecargo(List<LineaVistaPreviaRecargoInput> ls){var a=(ls==null?List.<LineaVistaPreviaRecargoInput>of():ls).stream().map(l->{BigDecimal base=scale(l.precioEsperado()).multiply(scale(l.cantidad())).subtract(scale(l.descuentoAplicado())).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal tax=base.multiply(l.tasaImpuestoEsperada()==null?BigDecimal.ZERO:l.tasaImpuestoEsperada()).divide(new BigDecimal("100"),SCALE,RoundingMode.HALF_UP);return new VistaPreviaRecargoDto.Asignacion(l.lineaId(),l.productoId(),base,scale(null),base,tax,base.add(tax));}).toList();return new ValidacionConfirmacion(new VistaPreviaRecargoDto(BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,false,null,null,null,null,false,a),null,null,null,null);}
 private static String fingerprint(SolicitudVistaPreviaRecargoInput s,VistaPreviaRecargoDto v){String lineas=v.asignaciones().stream().sorted(Comparator.comparing(x->x.lineaId().toString())).map(x->x.lineaId()+":"+x.recargo()).reduce("",(a,b)->a+"|"+b);String raw=s.operacionId()+"|"+s.recargo().alcance()+"|"+s.recargo().tipo()+"|"+s.recargo().valor()+"|"+s.recargo().conceptoId()+"|"+s.recargo().motivoId()+"|"+s.recargo().detalle()+lineas;try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private record Limite(boolean configurado,BigDecimal porcentaje,BigDecimal monto){}private record CalculoValidado(VistaPreviaRecargoDto vista,TipoRecargo concepto,MotivoRecargoVenta motivo){}public record ValidacionConfirmacion(VistaPreviaRecargoDto vista,TipoRecargo concepto,MotivoRecargoVenta motivo,RecargoVentaInput recargo,UUID autorizacionId){}
}
